<?php
declare(strict_types=1);
require __DIR__.'/acceso.php';require __DIR__.'/componentes/layout.php';Permissions::require('precios.ver');require_once dirname(__DIR__).'/modulos/catalogo/Catalogo.php';
$error='';$ready=false;$draftId='';try{$catalogo=new \RPV\Catalogo\Catalogo();$data=$catalogo->leer();$ready=true;}catch(Throwable $e){$failure=adminAuditFailure($pdo,'cargar_catalogo','producto',null,$e);$data=['revision'=>'','productos'=>[]];$error='El catalogo no esta disponible. Referencia: '.$failure['reference'].'.';}
if($_SERVER['REQUEST_METHOD']==='POST'){
    Csrf::validate($_POST['csrf']??null);Permissions::require('precios.editar');
    try{if(!$ready)throw new RuntimeException('El catalogo no esta disponible para editar.');if(($_POST['action']??'')!=='save_price')throw new InvalidArgumentException('Accion no valida.');$draftId=(string)($_POST['product_id']??'');$product=array_values(array_filter($data['productos'],static fn($p)=>$p['id']===$draftId))[0]??null;if(!$product)throw new InvalidArgumentException('El producto no existe.');$input=$product;$input['precio_clp']=(string)($_POST['precio_clp']??'');$input['modo_precio']=(string)($_POST['modo_precio']??'');$input['link_pago']=(string)($_POST['link_pago']??'');$input['aprobar']='1';$catalogo->guardar($draftId,$input,(string)($_POST['revision']??''),static function(PDO $db,array $before,array $after)use($draftId):void{adminAudit($db,'precio_actualizado','producto',$draftId,['antes'=>['precio_clp'=>$before['precio_clp'],'estado'=>$before['modo_precio'],'link_pago'=>$before['link_pago']],'despues'=>['precio_clp'=>$after['precio_clp'],'estado'=>$after['modo_precio'],'link_pago'=>$after['link_pago']]]);});notice('Precio actualizado y artefactos sincronizados en desarrollo.');go('/precios.php#'.rawurlencode($draftId));}catch(Throwable $e){$failure=adminAuditFailure($pdo,'save_price','producto',$draftId!==''?$draftId:null,$e,['revision'=>(string)($_POST['revision']??'')]);$error=($e instanceof InvalidArgumentException||$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar el precio.').' Referencia: '.$failure['reference'].'.';}
}
adminStart('Precios','precios','Catalogo comercial con control de revision');?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="section-head"><div><h2>Productos</h2><p>Cada guardado conserva historial y rechaza revisiones antiguas.</p></div><span class="badge"><?=count($data['productos'])?> productos</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Producto</th><th>Precio CLP</th><th>Estado</th><th>Link de pago</th><th>Accion</th></tr></thead><tbody><?php if(!$data['productos']):?><tr><td colspan="5" class="empty">No hay productos disponibles.</td></tr><?php endif;foreach($data['productos'] as $p):$fid='p-'.$p['id'];?><tr id="<?=h($p['id'])?>"><td><strong><?=h($p['nombre'])?></strong><br><small><?=h($p['categoria'])?></small></td><td><input form="<?=h($fid)?>" name="precio_clp" inputmode="numeric" pattern="[0-9.]+" required value="<?=h(number_format((float)$p['precio_clp'],0,',','.'))?>" aria-label="Precio de <?=h($p['nombre'])?>" <?=Permissions::allows('precios.editar')?'':'disabled'?>></td><td><select form="<?=h($fid)?>" name="modo_precio" <?=Permissions::allows('precios.editar')?'':'disabled'?>><?php foreach(['referencial'=>'Referencial','vigente'=>'Vigente','consultar'=>'A consultar'] as $v=>$label):?><option value="<?=$v?>" <?=$p['modo_precio']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></td><td><input form="<?=h($fid)?>" type="url" name="link_pago" maxlength="2048" pattern="https://.+" placeholder="https://..." value="<?=h((string)($p['link_pago']??''))?>" <?=Permissions::allows('precios.editar')?'':'disabled'?>></td><td><?php if(Permissions::allows('precios.editar')):?><form id="<?=h($fid)?>" method="post"><input type="hidden" name="csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="revision" value="<?=h($data['revision'])?>"><input type="hidden" name="product_id" value="<?=h($p['id'])?>"><input type="hidden" name="action" value="save_price"><button class="button primary small" type="submit">Guardar</button></form><?php else:?><span class="muted">Solo lectura</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><p class="muted">Precio permitido: $1 a $2.000.000 CLP. El enlace de pago debe usar HTTPS.</p><?php adminEnd();
